// Regenerate src/session-gate/gate-source.ts from src/session-gate/gate.js.
//
//   npm run embed-session-gate
//
// WHY A GENERATED MODULE (planning/49 Phase 3, I4): edge-gate-deploy uploads the gate's SOURCE TEXT, so
// the Worker bundle must carry gate.js as a string. Importing gate.js as text would need a wrangler.toml
// module rule, and every agency fork would have to merge that rule to keep deploying. A plain .ts module
// that exports the text needs nothing: wrangler bundles it like any other module. test/session-gate.test.ts
// fails when this generated file is out of date with gate.js, so the two cannot drift silently.
//
// Node only (a build-time helper); the Worker never runs this file.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const gatePath = fileURLToPath(new URL("../src/session-gate/gate.js", import.meta.url));
const outputPath = fileURLToPath(new URL("../src/session-gate/gate-source.ts", import.meta.url));

const gateSource = readFileSync(gatePath, "utf8");

// JSON.stringify gives a valid TypeScript string literal for any text.
const output =
  "// GENERATED by scripts/embed-session-gate.mjs from src/session-gate/gate.js. Do not edit by hand.\n" +
  "// test/session-gate.test.ts fails when this file is out of date. Regenerate: npm run embed-session-gate\n" +
  "\n" +
  "/** The session edge gate's source text, uploaded by edge-gate-deploy (src/actuate-edge-gate.ts). */\n" +
  `export const SESSION_GATE_SOURCE: string = ${JSON.stringify(gateSource)};\n`;

writeFileSync(outputPath, output);
console.log(`wrote ${outputPath} (${gateSource.length} characters of gate source)`);
